let rayvnConfig = global.get('rayvnConfig') || {};

if (msg.topic === 'rayvn_api_key') {
    rayvnConfig.apiKey = msg.payload;
} else if (msg.topic === 'log_name') {
    rayvnConfig.logName = msg.payload;
}

global.set('rayvnConfig', rayvnConfig);

return null;

let wasosConfig = global.get('wasosConfig') || {};

if (msg.topic === 'wasos_username') {
    wasosConfig.username = msg.payload;
} else if (msg.topic === 'wasos_password') {
    // IKKE lagre passordet - sett det bare på meldingen
    msg.password = msg.payload;
    return msg;  // Send direkte til neste node
} else if (msg.topic === 'chatroom_name') {
    wasosConfig.chatroom = msg.payload;
}

global.set('wasosConfig', wasosConfig);

return null;

let rayvnConfig = global.get('rayvnConfig') || {};

node.warn('Retrieved Rayvn config: ' + JSON.stringify({ ...rayvnConfig, apiKey: '***' }));

if (!rayvnConfig.apiKey || !rayvnConfig.logName) {
    node.warn('Missing required Rayvn fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde Rayvn-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}

// Prepare to fetch logs from Rayvn
msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};
msg.url = "https://api.rayvn.global/logs";
msg.rayvnConfig = rayvnConfig; // Pass config along

return msg;

let wasosConfig = global.get('wasosConfig') || {};
let password = global.get('temp_password');  // Hent midlertidig passord

node.warn('Retrieved config (no password): ' + JSON.stringify(wasosConfig));

if (!wasosConfig.username || !password || !wasosConfig.chatroom) {
    node.warn('Missing required WaSOS fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde WaSOS-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return [msg, null];
}

const wasosBaseUrl = "https://dev.wasos.no";

msg.username = wasosConfig.username;
msg.password = password;
msg.url = wasosBaseUrl;

// Slett midlertidig passord etter bruk
global.set('temp_password', null);

const chatroomUrl = `${wasosBaseUrl}/api/chat/messages/${wasosConfig.chatroom}`;
global.set('wasosChatroomUrl', chatroomUrl);
global.set('wasosChatroomName', wasosConfig.chatroom);

msg.payload = `WaSOS-konfigurasjon lagret! Chatrom: ${wasosConfig.chatroom}`;
msg.topic = 'Success';
msg.color = '#4CAF50';

return [null, msg];

let chatroom = global.get('wasosChatroomName');

if (msg.payload && msg.payload.nonce) {
    // Login vellykket
    msg.payload = `WaSOS-tilkobling vellykket! Chatrom: ${chatroom}`;
    msg.color = '#4CAF50';
} else {
    // Login feilet
    msg.payload = 'WaSOS-tilkobling feilet. Sjekk brukernavn og passord.';
    msg.color = '#F44336';
}

return msg;

const rayvnConfig = msg.rayvnConfig;
const logName = rayvnConfig.logName.trim();

try {
    const logs = JSON.parse(msg.payload);

    // Find matching logs (case-insensitive exact match)
    const matches = logs.filter(log =>
        log.name.toLowerCase() === logName.toLowerCase()
    );

    if (matches.length === 0) {
        msg.payload = `Logg '${logName}' ble ikke funnet i Rayvn.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    if (matches.length > 1) {
        // Multiple logs with same name - need user to choose
        msg.payload = `Fant ${matches.length} logger med navn '${logName}'. Vennligst kontakt administrator.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    // Success! Store the log ID
    const logId = matches[0].id;
    global.set('rayvnLogId', logId);

    msg.payload = `Rayvn-konfigurasjon lagret! Logg: ${logName} (ID: ${logId})`;
    msg.topic = 'Success';
    msg.color = '#4CAF50';

    return msg;

} catch (e) {
    msg.payload = 'Feil ved henting av Rayvn-logger: ' + e.message;
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}
